// ===== 37-hitfx: the match-hit flash (flashyfeather hit-animations-vol2, effect 4) =====
// Repacked by tools/hitfx-pack.py from the gitignored source pack: 24 frames of 128 px
// sampled evenly from the 60-frame 4096px sheet, played at 40 fps (~0.60 s).
// ⚠️ To try another effect: python3 tools/hitfx-pack.py <n> — the file is fully regenerated.
// The consumer is spawnHitFx (70-fx); the sprite billboards itself, normal blending — the
// additive look of the source dies on our light sky, the alpha channel carries it instead.
const HITFX = { cols: 6, rows: 4, n: 24, fps: 40 };
const HITFX_PNG = 'data:image/png;base64,';
let _hitFxTex = null;
function hitFxBaseTexture(){
  if (_hitFxTex) return _hitFxTex;
  const img = new Image();
  const tex = new THREE.Texture(img);
  img.onload = () => { tex.needsUpdate = true; };
  img.src = HITFX_PNG;
  tex.minFilter = THREE.LinearFilter; tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = false;
  _hitFxTex = tex;
  return tex;
}
